import { NavLink, Link } from "react-router-dom";
import {
  LayoutDashboard,
  Users,
  UserPlus,
  Receipt,
  ArrowRight,
  Link2,
  Settings,
  ChevronRight,
  IndianRupee,
} from "lucide-react";

const mainLinks = [
  { to: "/", label: "Overview", icon: LayoutDashboard },
  { to: "/groups", label: "Groups", icon: Users },
  { to: "/friends", label: "Friends", icon: UserPlus },
  { to: "/expenses", label: "Expenses", icon: Receipt },
  { to: "/settlements", label: "Settlements", icon: ArrowRight, badge: 3 },
];

const quickLinks = [
  { to: "/join-group", label: "Join a group", icon: Link2 },
  { to: "/settings", label: "Settings", icon: Settings },
];

function NavItem({ item }) {
  const Icon = item.icon;
  return (
    <NavLink
      to={item.to}
      end={item.to === "/"}
      className={({ isActive }) =>
        `w-full flex items-center gap-4 px-5 py-3.5 rounded-xl font-medium transition-colors ${
          isActive
            ? "bg-brand/30 text-white"
            : "text-slate-300 hover:bg-white/5 hover:text-white"
        }`
      }
    >
      <Icon size={20} strokeWidth={1.8} />
      <span className="flex-1">{item.label}</span>
      {item.badge && (
        <span className="w-6 h-6 rounded-full bg-brand text-white text-xs font-semibold flex items-center justify-center">
          {item.badge}
        </span>
      )}
    </NavLink>
  );
}

function Sidebar() {
  return (
    <aside className="flex w-64 xl:w-72 shrink-0 h-screen flex-col overflow-y-auto bg-ink text-white px-4 py-6">
      {/* Logo */}
      <Link to="/" className="flex items-center gap-3 px-2 mb-10">
        <div className="w-11 h-11 rounded-xl bg-brand flex items-center justify-center">
          <IndianRupee size={22} />
        </div>
        <span className="text-2xl font-bold tracking-tight">
          fair<span className="text-brand">share</span>
        </span>
      </Link>

      {/* Main nav */}
      <p className="px-3 mb-3 font-mono text-[11px] tracking-widest text-slate-500 uppercase">
        Your college circle
      </p>
      <nav className="flex flex-col gap-1.5">
        {mainLinks.map((item) => (
          <NavItem key={item.to} item={item} />
        ))}
      </nav>

      {/* Quick links */}
      <p className="px-3 mt-10 mb-3 font-mono text-[11px] tracking-widest text-slate-500 uppercase">
        Quick links
      </p>
      <nav className="flex flex-col gap-1.5">
        {quickLinks.map((item) => (
          <NavItem key={item.to} item={item} />
        ))}
      </nav>

      {/* Profile card */}
      <Link
        to="/profile"
        className="mt-auto pt-0 flex items-center gap-3 p-4 rounded-2xl bg-inkSoft hover:bg-white/10 transition-colors"
      >
        <div className="w-11 h-11 rounded-full border-2 border-brand bg-brand/20 flex items-center justify-center text-sm font-semibold">
          KS
        </div>
        <div className="flex-1">
          <p className="font-semibold leading-tight">Krisha Shah</p>
          <p className="text-sm text-slate-400">Gujarat student</p>
        </div>
        <ChevronRight size={18} className="text-slate-400" />
      </Link>
    </aside>
  );
}

export default Sidebar;
